const spreads=[...document.querySelectorAll('.spread')];let cur=0;function nums(s,i){if(s.hasAttribute('data-nofoot'))return;const L=s.querySelector('.pg.l'),R=s.querySelector('.pg.r');if(L){const d=document.createElement('div');d.className='pnum';d.textContent='InnBuddy ― VOL.01';L.appendChild(d);} if(R){const d=document.createElement('div');d.className='pnum';d.textContent='田舎の美を、世界へ。';R.appendChild(d);}} spreads.forEach(nums);function show(n){n=Math.max(0,Math.min(spreads.length-1,n));spreads[cur].classList.remove('on');cur=n;spreads[cur].classList.add('on');document.getElementById('cnt').textContent='SPREAD '+(cur+1)+' / '+spreads.length;} document.getElementById('next').onclick=()=>show(cur+1);document.getElementById('prev').onclick=()=>show(cur-1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' '||e.key==='PageDown')show(cur+1);if(e.key==='ArrowLeft'||e.key==='PageUp')show(cur-1);if(e.key==='Escape')document.getElementById('toc').classList.remove('on');});let tx=null;document.addEventListener('touchstart',e=>{tx=e.touches[0].clientX});document.addEventListener('touchend',e=>{if(tx===null)return;const dx=e.changedTouches[0].clientX-tx;if(dx<-40)show(cur+1);if(dx>40)show(cur-1);tx=null;});const toc=document.getElementById('toc'),list=document.getElementById('toclist');spreads.forEach((s,i)=>{if(!s.dataset.toc)return;const r=document.createElement('div');r.className='row';r.innerHTML='<span class="n">p.'+(s.dataset.p||'--')+'</span><span class="l">'+s.dataset.toc+'</span><span class="s">'+(s.dataset.s||'')+'</span>';r.onclick=()=>{toc.classList.remove('on');show(i)};list.appendChild(r);});document.getElementById('tocbtn').onclick=()=>toc.classList.add('on');document.getElementById('tocclose').onclick=()=>toc.classList.remove('on');show(0);